38	  const diag = [];
39	  for (let k = 0; k <= K; k++) diag.push(new Uint8Array(N - k));
40	  const base = centerBitIndex(N);
41	  let t = 0;
42	  for (const row of rows(N)) {
43	    const s = row.toString(2);
44	    const len = s.length;
45	    for (let k = 0; k <= K && k <= t; k++) {
46	      const pos = base - (t - k);
47	      diag[k][t - k] = pos < len && s.charCodeAt(len - 1 - pos) === 49 ? 1 : 0;
