 * @param {{trim?: boolean}} [options]
 * @returns {Uint8Array}
 */
export function centerColumnBits(generations, options) {
  const out = new Uint8Array(generations);
  let i = 0;
  for (const bit of centerColumn(generations, options)) out[i++] = bit;
